import { useAppBridge } from '@shopify/app-bridge-react';

const shopify = useAppBridge();
shopify.toast.show('Salvo com sucesso');

export async function loader({ request }) {
  const url = new URL(request.url);
  const cursor = url.searchParams.get("cursor");
  const { admin } = await authenticate.admin(request);
  const response = await admin.graphql(`#graphql
    query($cursor: String) {
      products(first: 10, after: $cursor) {
        nodes { id title }
        pageInfo { hasNextPage endCursor }
      }
    }`, { variables: { cursor } });
  return (await response.json()).data;
}

import { IndexTable, Button } from '@shopify/polaris';
import { useLoaderData, useNavigate } from 'react-router';

export default function Index() {
  const { products, pageInfo } = useLoaderData();
  const navigate = useNavigate();
  return (
    <>
      <IndexTable /* ...configuração com products */ />
      {pageInfo.hasNextPage && (
        <Button onClick={() => navigate(`?cursor=${pageInfo.endCursor}`)}>
          Carregar mais
        </Button>
      )}
    </>
  );
}

const shopify = useAppBridge();
// dentro de um useEffect que observa a mudança de 'products':
shopify.toast.show(`${products.length} produtos carregados`);
